package changelog

import "strings"

func lokiCases() {
	lokiCase("c1", "change", "issue example: commit subjects between v1.2.0 and HEAD", func() any {
		return strings.Join(CommitsCmd("v1.2.0", "HEAD"), " ")
	})
	lokiCase("c2", "change", "commit subjects between v1.0.0 and v1.1.0", func() any {
		return strings.Join(CommitsCmd("v1.0.0", "v1.1.0"), " ")
	})
	lokiCase("c3", "change", "argument count of the commit subjects command", func() any {
		return len(CommitsCmd("v1.2.0", "HEAD"))
	})

	lokiCase("k1", "keep", "authors command keeps --no-merges and author format", func() any {
		return strings.Join(AuthorsCmd("v1.0.0", "HEAD"), " ")
	})
	lokiCase("k2", "keep", "shared log prefix with a custom format", func() any {
		return strings.Join(logArgs("%H"), " ")
	})
	lokiCase("k3", "keep", "last tag command", func() any {
		return strings.Join(LastTagCmd(), " ")
	})
	lokiCase("k4", "keep", "render skips blank and whitespace-only subjects", func() any {
		return Render("v1.1.0", []string{"Add export", "  ", "", "Fix crash on empty config"})
	})
	lokiCase("k5", "keep", "render with no subjects", func() any {
		return Render("v2.0.0", nil)
	})
	lokiCase("k6", "keep", "render trims surrounding whitespace from subjects", func() any {
		return Render("v1.3.0", []string{"  Tidy logging  "})
	})
	lokiCase("k7", "keep", "contributors dedupes and sorts author lines", func() any {
		return Contributors([]string{"bo <bo@x.io>", "al <al@x.io>", "bo <bo@x.io>"})
	})
	lokiCase("k8", "keep", "contributors ignores blank lines and returns nothing for empty input", func() any {
		return Contributors([]string{"", "   "})
	})
}
